{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "Ist Binder wirklich kostenlos?",
        "acceptedAnswer": { "@type": "Answer", "text": "Ja. Alles in der App ist kostenlos: kein Pro-Tarif, keine bezahlten Boosts, keine verpixelten Likes und keine künstliche Tagesgrenze. Die Produkt-Roadmap enthält keine kostenpflichtige Stufe." }
      },
      {
        "@type": "Question",
        "name": "Kann mir jemand schreiben, bevor ich zurückgelikt habe?",
        "acceptedAnswer": { "@type": "Answer", "text": "Nein. Nur Mitglieder eines aktiven, gegenseitigen Matches können Nachrichten lesen oder senden. Unmatch und Block beenden das Gespräch auf dem Server, nicht nur auf deinem Bildschirm." }
      },
      {
        "@type": "Question",
        "name": "Zeigt Binder anderen Nutzern meinen genauen Standort oder mein Geburtsdatum?",
        "acceptedAnswer": { "@type": "Answer", "text": "Nein. Genaue Koordinaten bleiben privat für serverseitige Distanzprüfungen und erreichen nie ein anderes Gerät. Alter und gerundete Entfernung werden serverseitig abgeleitet." }
      },
      {
        "@type": "Question",
        "name": "Welche Sprachen unterstützt Binder?",
        "acceptedAnswer": { "@type": "Answer", "text": "Binder ist vollständig in {{@language-count}} Sprachen übersetzt und folgt der Sprache, auf die dein Telefon eingestellt ist. Du kannst die Wahl jederzeit in der App ändern." }
      },
      {
        "@type": "Question",
        "name": "Wie lösche ich mein Binder-Konto?",
        "acceptedAnswer": { "@type": "Answer", "text": "Über Profil und dann Konto-Einstellungen in der App oder über die öffentliche Löschseite, die auch nach der Deinstallation der App erreichbar bleibt." }
      }
    ]
  }
